    def sign(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pos(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return x[0], x[1]
        return None

    def dist(a, b):
        if a is None or b is None:
            return 10**9
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(a, b):
        if a is None or b is None:
            return [0, 0]
        return [sign(b[0] - a[0]), sign(b[1] - a[1])]

